CREATE OR REPLACE FUNCTION orulo_audit.pilot_auth(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb;
begin
 if (select count(*) from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED')<>1 then raise exception 'PILOT_EXPLICIT_AUTHORIZATION_REQUIRED'; end if;
 select event into a from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED';
 if a->>'mode' is distinct from 'PILOT_ONE_BUILDING' or a->>'buildingId' is distinct from '43126' or
    a->>'manifestHash' is distinct from '1c8b002b5a3b4b6caf614e3b4e6d84383b8e306ae2773f3d7de48cc7daaa6d03' or
    (a->>'expiresAt')::timestamptz<clock_timestamp() or a->>'expiresAt' is null then raise exception 'PILOT_AUTHORIZATION_INVALID_OR_EXPIRED'; end if;
 return a;
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.append(p_run uuid, p_sequence bigint, p_previous text, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n bigint; previous text; e orulo_audit.entries%rowtype; c text;
begin
 perform orulo_audit.lock_run(p_run);
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('FINISHED','ABORTED')) then raise exception 'AUDIT_RUN_CLOSED'; end if;
 select sequence+1,hash into n,previous from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 n:=coalesce(n,1);previous:=coalesce(previous,'');
 if p_sequence is distinct from n or p_previous is distinct from previous then raise exception 'AUDIT_SEQUENCE_CONFLICT'; end if;
 if jsonb_typeof(p_event) is distinct from 'object' or not(p_event ? 'eventUuid') or not(p_event ? 'type') then raise exception 'AUDIT_INVALID_EVENT'; end if;
 c:=jsonb_build_object('runUuid',p_run,'sequence',n,'previousHash',previous,'event',p_event)::text;
 insert into orulo_audit.entries(run_uuid,sequence,event_uuid,operation_uuid,kind,event,previous_hash,canonical,hash)
 values(p_run,n,(p_event->>'eventUuid')::uuid,(p_event->>'operationId')::uuid,p_event->>'type',p_event,previous,c,encode(sha256(convert_to(c,'UTF8')),'hex')) returning * into e;
 return jsonb_build_object('runUuid',p_run,'sequence',n,'hash',e.hash,'eventUuid',e.event_uuid);
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.control_paged(p_action text, p_run uuid DEFAULT NULL::uuid, p_sequence bigint DEFAULT NULL::bigint, p_previous_hash text DEFAULT NULL::text, p_event jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare s orulo_audit.snapshot_sets%rowtype; k text; keys_now uuid[]; wanted uuid[]; n integer; size integer;
 rows_json jsonb; ack jsonb; event jsonb; inserted jsonb; deleted jsonb;
begin
 perform orulo_audit.require_service();
 if p_action='health' then
  return orulo_audit.control_v1('health')||jsonb_build_object('version',2,'snapshotProtocol','paged-v2');
 end if;
 if p_action='snapshot' then raise exception 'AUDIT_PAGED_SNAPSHOT_REQUIRED'; end if;
 if p_action='append' and p_event->>'type'='INTENT' then
  perform orulo_audit.lock_run(p_run);
  if exists(select 1 from orulo_audit.snapshot_sets t where t.run_uuid=p_run and not exists(select 1 from orulo_audit.entries e where e.run_uuid=p_run and e.kind=t.kind)) then raise exception 'AUDIT_CAPTURE_ALREADY_OPEN'; end if;
 end if;
 if p_action not in ('snapshot_begin','snapshot_page','snapshot_seal') then
  return orulo_audit.control_v1(p_action,p_run,p_sequence,p_previous_hash,p_event);
 end if;
 perform orulo_audit.lock_run(p_run);
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('FINISHED','ABORTED')) then raise exception 'AUDIT_RUN_CLOSED'; end if;
 -- Only one capture at a time; no snapshots interleaved with an operational INTENT.
 if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
 k:=p_event->>'kind';
 if k is null or k not in ('BASELINE_V2','READBACK_V2') then raise exception 'AUDIT_SNAPSHOT_KIND_INVALID'; end if;
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind=k) then raise exception 'AUDIT_SNAPSHOT_SEALED'; end if;
 if p_action='snapshot_begin' then
  if exists(select 1 from orulo_audit.snapshot_sets t where t.run_uuid=p_run and not exists(select 1 from orulo_audit.entries e where e.run_uuid=p_run and e.kind=t.kind)) then raise exception 'AUDIT_CAPTURE_ALREADY_OPEN'; end if;
  if k='READBACK_V2' and not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2') then raise exception 'AUDIT_BASELINE_REQUIRED'; end if;
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into keys_now from public.properties;
  ack:=orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','SNAPSHOT_BEGIN','kind',k,'eventUuid',p_event->>'eventUuid',
   'keys',to_jsonb(keys_now),'columns',orulo_audit.columns_v2(),'consistency','bounded-read-committed-window','snapshotProtocol','paged-v2'));
  insert into orulo_audit.snapshot_sets values(p_run,k,keys_now,orulo_audit.columns_v2(),p_sequence);
  return ack;
 end if;
 select * into s from orulo_audit.snapshot_sets where run_uuid=p_run and kind=k;
 if not found then raise exception 'AUDIT_SNAPSHOT_BEGIN_REQUIRED'; end if;
 if s.columns is distinct from orulo_audit.columns_v2() then raise exception 'AUDIT_SNAPSHOT_SCHEMA_CHANGED'; end if;
 select count(*) into n from orulo_audit.snapshot_records where run_uuid=p_run and kind=k;
 if p_action='snapshot_page' then
  size:=coalesce((p_event->>'size')::integer,50);
  if size<1 or size>100 then raise exception 'AUDIT_PAGE_SIZE_INVALID'; end if;
  if n>=cardinality(s.keys) then raise exception 'AUDIT_NO_MORE_PAGES'; end if;
  if (p_event->>'offset')::integer is distinct from n then raise exception 'AUDIT_PAGE_CURSOR_CONFLICT'; end if;
  wanted:=s.keys[n+1:n+size];
  -- PK probes for only this fixed UUID slice. Materialize the canonical full row
  -- once: the old inlined expression serialized each large raw_data twice.
  with selected as materialized(
   select u.id,p.external_id,p.raw_data,p.updated_at,
   case when p.id is not null then to_jsonb(p)||jsonb_build_object('created_at',p.created_at at time zone 'UTC','updated_at',p.updated_at at time zone 'UTC') end canonical
   from unnest(wanted) u(id) left join lateral(select * from public.properties p where p.id=u.id limit 1) p on true
  ) select jsonb_agg(jsonb_build_array(id,external_id,coalesce(raw_data->>'building_id',raw_data->'building'->>'id',''),updated_at at time zone 'UTC',md5(canonical::text),md5((canonical-'updated_at')::text)) order by id) into rows_json from selected;
  ack:=orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','SNAPSHOT_PAGE','kind',k,'eventUuid',p_event->>'eventUuid',
   'offset',n,'count',cardinality(wanted),'records',rows_json));
  insert into orulo_audit.snapshot_records select p_run,k,(r->>0)::uuid,r,p_sequence from jsonb_array_elements(rows_json) r;
  return ack;
 end if;
 if n<>cardinality(s.keys) then raise exception 'AUDIT_SNAPSHOT_INCOMPLETE'; end if;
 select coalesce(array_agg(id order by id),'{}'::uuid[]) into keys_now from public.properties;
 select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into inserted from (select unnest(keys_now) id except select unnest(s.keys)) x;
 select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into deleted from (select unnest(s.keys) id except select unnest(keys_now)) x;
 event:=jsonb_build_object('type',k,'eventUuid',p_event->>'eventUuid','snapshot',jsonb_build_object(
  'format','paged-v2','key','id','beginSequence',s.begin_sequence,'processed',n,
  'algorithm','MD5 PostgreSQL canonical JSONB; timestamps UTC','excludedContentFields',jsonb_build_array('updated_at'),
  'columns',s.columns,'membershipStable',keys_now=s.keys and not exists(select 1 from orulo_audit.snapshot_records where run_uuid=p_run and kind=k and record->>4 is null),
  'insertedDuringCapture',inserted,'deletedDuringCapture',deleted,'keysAtSeal',to_jsonb(keys_now)));
 return orulo_audit.append(p_run,p_sequence,p_previous_hash,event);
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.pilot_cas_guard(p_run uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare a jsonb; i orulo_audit.entries%rowtype; b orulo_audit.entries%rowtype; expected public.properties%rowtype; j jsonb;
begin
 perform orulo_audit.require_service();perform orulo_audit.lock_run(p_run);a:=orulo_audit.pilot_auth(p_run);
 select * into i from orulo_audit.entries where run_uuid=p_run and operation_uuid=p_operation and kind='INTENT';
 if not found then raise exception 'AUDIT_DURABLE_INTENT_REQUIRED'; end if;
 if not(a->'targetIds' ? (i.event->>'id')) or coalesce(i.event->'expected'->'raw_data'->>'building_id',i.event->'expected'->'raw_data'->'building'->>'id') is distinct from '43126' then raise exception 'PILOT_ROW_SCOPE_DENIED'; end if;
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='CAS_RESULT' and event->>'id'=i.event->>'id') then raise exception 'PILOT_ROW_ALREADY_ATTEMPTED_USE_RECOVERY'; end if;
 select * into b from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2';
 if not found or b.created_at<clock_timestamp()-interval '5 minutes' or b.event->'snapshot'->>'membershipStable' is distinct from 'true' or
    (b.event->'snapshot'->>'beginSequence')::bigint <= (select sequence from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') or
    b.event->'snapshot'->'columns' is distinct from orulo_audit.columns_v2() then raise exception 'PILOT_FRESH_BASELINE_REQUIRED'; end if;
 select * into expected from jsonb_populate_record(null::public.properties,i.event->'expected');
 j:=to_jsonb(expected)||jsonb_build_object('created_at',expected.created_at at time zone 'UTC','updated_at',expected.updated_at at time zone 'UTC');
 if not exists(select 1 from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and id=expected.id and record->>2='43126' and record->>4=md5(j::text)) then raise exception 'PILOT_EXPECTED_DIFFERS_FROM_BASELINE'; end if;
 return orulo_audit.audited_cas_core(p_run,p_operation);
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.authorize_single_pilot(p_run uuid, p_expected_head text, p_github_run_id text, p_control_sha text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET synchronous_commit TO 'on'
AS $function$
declare e orulo_audit.entries%rowtype; r orulo_audit.runs%rowtype; targets jsonb;
begin
 if current_setting('role',true)='service_role' or session_user not in ('postgres','supabase_admin') then raise insufficient_privilege; end if;
 if length(trim(p_reason))<10 or p_reason is null then raise exception 'PILOT_ADMIN_REASON_REQUIRED'; end if;
 perform orulo_audit.lock_run(p_run);
 select * into r from orulo_audit.runs where run_uuid=p_run;
 select * into e from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 if r.github_run_id is distinct from p_github_run_id or r.metadata->>'workflowSha' is distinct from p_control_sha or
    coalesce(p_control_sha,'') !~ '^[0-9a-f]{40}$' or e.hash is distinct from p_expected_head or
    e.kind<>'CLIENT_READBACK' or e.event->>'stage' is distinct from 'PILOT_PLAN' or
    e.event->>'buildingId' is distinct from '43126' or
    exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('WRITE_AUTHORIZED','BASELINE_V2','ABORTED','FINISHED')) then raise exception 'PILOT_PLAN_OR_HEAD_MISMATCH'; end if;
 targets:=orulo_audit.pilot_targets();
 if jsonb_array_length(targets)<1 or jsonb_array_length(targets)>500 or targets is distinct from e.event->'targetIds' then raise exception 'PILOT_TARGETS_CHANGED'; end if;
 return orulo_audit.append(p_run,e.sequence+1,e.hash,jsonb_build_object('type','WRITE_AUTHORIZED','eventUuid',gen_random_uuid(),
  'mode','PILOT_ONE_BUILDING','buildingId','43126','targetIds',targets,'planSequence',e.sequence,'controlSha',p_control_sha,
  'manifestHash',r.metadata->>'manifestHash','expiresAt',clock_timestamp()+interval '30 minutes','reason',p_reason));
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.control_pilot(p_action text, p_run uuid DEFAULT NULL::uuid, p_sequence bigint DEFAULT NULL::bigint, p_previous_hash text DEFAULT NULL::text, p_event jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare a jsonb; e orulo_audit.entries%rowtype; p public.properties%rowtype; j jsonb; bad bigint; written bigint; comparison jsonb;
begin
 perform orulo_audit.require_service();
 if p_action='health' then return orulo_audit.control_paged('health')||jsonb_build_object('pilotProtocol',1); end if;
 if p_action='pilot_status' then
  select * into e from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED' order by sequence desc limit 1;
  if not found then return 'null'::jsonb; end if;
  perform orulo_audit.pilot_auth(p_run);
  return jsonb_build_object('runUuid',p_run,'sequence',e.sequence,'hash',e.hash,'eventUuid',e.event_uuid);
 end if;
 if p_action='pilot_targets' then return orulo_audit.pilot_targets(); end if;
 if p_action='pilot_row' then
  select * into p from public.properties where id=(p_event->>'id')::uuid;
  if not found or not orulo_audit.scope_ok(to_jsonb(p)) or coalesce(p.raw_data->>'building_id',p.raw_data->'building'->>'id')<>'43126' then raise exception 'PILOT_ROW_SCOPE_DENIED'; end if;
  j:=to_jsonb(p)||jsonb_build_object('created_at',p.created_at at time zone 'UTC','updated_at',p.updated_at at time zone 'UTC');
  return jsonb_build_object('row',to_jsonb(p),'fullHash',md5(j::text),'contentHash',md5((j-'updated_at')::text));
 end if;
 if p_action='append' and p_event->>'type'='INTENT' then
  perform orulo_audit.lock_run(p_run);a:=orulo_audit.pilot_auth(p_run);
  if not(a->'targetIds' ? (p_event->>'id')) or coalesce(p_event->'expected'->'raw_data'->>'building_id',p_event->'expected'->'raw_data'->'building'->>'id') is distinct from '43126' then raise exception 'PILOT_ROW_SCOPE_DENIED'; end if;
 end if;
 if p_action<>'pilot_finish' then return orulo_audit.control_paged(p_action,p_run,p_sequence,p_previous_hash,p_event); end if;
 perform orulo_audit.lock_run(p_run);a:=orulo_audit.pilot_auth(p_run);
 if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
 if (select count(*) from orulo_audit.entries where run_uuid=p_run and kind in ('BASELINE_V2','READBACK_V2'))<>2 then raise exception 'AUDIT_TWO_SNAPSHOTS_REQUIRED'; end if;
 comparison:=orulo_audit.compare_v2(p_run);
 if comparison->>'schemaMatch' is distinct from 'true' or comparison->>'captureStable' is distinct from 'true' then raise exception 'PILOT_SNAPSHOT_INTEGRITY_FAILED'; end if;
 -- Only exact trusted CAS receipts justify an IN_SCOPE delta. Everything else
 -- must be unchanged or have proven stable OUT_OF_SCOPE bindings, as in PR #84.
 with b as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and record->>4 is not null),
 d as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='READBACK_V2' and record->>4 is not null),
 x as(select coalesce(b.id,d.id) id,b.record before,d.record after from b full join d using(id)),
 checked as(select x.*,c.event->'result' result from x left join orulo_audit.entries c on c.run_uuid=p_run and c.kind='CAS_RESULT' and c.event->>'id'=x.id::text)
 select count(*) filter(where not coalesce(
  case when result is not null then result->>'status'='UPDATED' and result->'receipt'->>'verified'='true'
   and before->>4=result->'receipt'->>'beforeFullHash' and after->>4=result->'receipt'->>'afterFullHash'
   and before->>5=result->'receipt'->>'expectedBeforeContentHash' and after->>5=result->'receipt'->>'expectedAfterContentHash'
  when before->>4=after->>4 then true
  else (before is null or ((before->>2)~'^[1-9][0-9]*$' and not orulo_audit.scope_ok(jsonb_build_object('state','SP','source','novos','active',true,'raw_data',jsonb_build_object('building_id',before->>2)))))
   and (after is null or ((after->>2)~'^[1-9][0-9]*$' and not orulo_audit.scope_ok(jsonb_build_object('state','SP','source','novos','active',true,'raw_data',jsonb_build_object('building_id',after->>2)))))
   and (before is null or after is null or before->>2=after->>2) end,false)),
 count(*) filter(where result->>'status'='UPDATED') into bad,written from checked;
 if bad<>0 or written<1 then raise exception 'PILOT_UNEXPLAINED_DIVERGENCE_OR_NO_UPDATES'; end if;
 return orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','FINISHED','eventUuid',p_event->>'eventUuid',
  'mode','PILOT_ONE_BUILDING','buildingId','43126','rowsWritten',written,'comparison',comparison,'writeEnabled',false));
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.batch_inventory(batch_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c jsonb; bids text[]; live jsonb; x jsonb;
begin
 c:=orulo_audit.batch_catalog()->'batches'->batch_id;if c is null then raise exception 'BATCH_UNKNOWN'; end if;
 select array_agg(v) into bids from jsonb_array_elements_text(c->'buildingIds')v;
 with matched as materialized(
  select id,raw_data->>'building_id' bid,raw_data raw from public.properties where source='novos' and state='SP' and active is true and raw_data->>'building_id'=any(bids)
  union all select id,raw_data->'building'->>'id',raw_data from public.properties where source='novos' and state='SP' and active is true and raw_data->>'building_id' is null and raw_data->'building'->>'id'=any(bids))
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'buildingId',bid,'missingPlanIds',orulo_audit.batch_missing_ids(raw)) order by id) filter(where orulo_audit.batch_missing_ids(raw)<>'[]'::jsonb),'[]'::jsonb) into live from matched;
 for x in select * from jsonb_array_elements(live) loop
  if not exists(select 1 from jsonb_array_elements(c->'targets')a where a->>'id'=x->>'id' and a->>'buildingId'=x->>'buildingId' and (a->'missingPlanIds') @> (x->'missingPlanIds')) then raise exception 'BATCH_MANIFEST_DRIFT'; end if;
 end loop;
 return jsonb_build_object('batchId',batch_id,'masterHash',orulo_audit.batch_catalog()->>'masterHash','batchManifestHash',c->>'hash','targets',live);
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.batch_auth(r uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb; c jsonb;
begin
 if (select count(*) from orulo_audit.entries where run_uuid=r and kind='WRITE_AUTHORIZED')<>1 then raise exception 'BATCH_EXPLICIT_AUTHORIZATION_REQUIRED'; end if;
 select event into a from orulo_audit.entries where run_uuid=r and kind='WRITE_AUTHORIZED';c:=orulo_audit.batch_catalog()->'batches'->(a->>'batchId');
 if a->>'mode' is distinct from 'BATCH_IMAGES' or c is null or c->>'released' is distinct from 'true' or a->>'masterHash' is distinct from orulo_audit.batch_catalog()->>'masterHash' or a->>'batchManifestHash' is distinct from c->>'hash' or a->>'expiresAt' is null or (a->>'expiresAt')::timestamptz<clock_timestamp() then raise exception 'BATCH_AUTHORIZATION_INVALID_OR_EXPIRED'; end if;
 return a;
end$function$

CREATE OR REPLACE FUNCTION public.orulo_audit_control(p_action text, p_run uuid DEFAULT NULL::uuid, p_sequence bigint DEFAULT NULL::bigint, p_previous_hash text DEFAULT NULL::text, p_event jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare a jsonb;e orulo_audit.entries%rowtype;p public.properties%rowtype;j jsonb;c jsonb;bad bigint;written bigint;comparison jsonb;
begin
 perform orulo_audit.require_service();
 if p_action='health' then return orulo_audit.control_pilot('health')||jsonb_build_object('batchProtocol',1,'batchMasterHash',orulo_audit.batch_catalog()->>'masterHash'); end if;
 if p_action='batch_inventory' then return orulo_audit.batch_inventory(p_event->>'batchId'); end if;
 if p_action='batch_row' then
  c:=orulo_audit.batch_catalog()->'batches'->(p_event->>'batchId');select * into p from public.properties where id=(p_event->>'id')::uuid;
  if not found or not orulo_audit.scope_ok(to_jsonb(p)) or not exists(select 1 from jsonb_array_elements(c->'targets')x where x->>'id'=p.id::text and x->>'buildingId'=coalesce(p.raw_data->>'building_id',p.raw_data->'building'->>'id')) then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
  j:=to_jsonb(p)||jsonb_build_object('created_at',p.created_at at time zone 'UTC','updated_at',p.updated_at at time zone 'UTC');return jsonb_build_object('row',to_jsonb(p),'fullHash',md5(j::text),'contentHash',md5((j-'updated_at')::text));
 end if;
 if p_action='batch_status' then
  select * into e from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED';if not found then return 'null'::jsonb; end if;perform orulo_audit.batch_auth(p_run);
  return jsonb_build_object('runUuid',p_run,'sequence',e.sequence,'hash',e.hash,'eventUuid',e.event_uuid);
 end if;
 if p_action='append' and p_event->>'type'='INTENT' and exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED' and event->>'mode'='BATCH_IMAGES') then
  perform orulo_audit.lock_run(p_run);a:=orulo_audit.batch_auth(p_run);
  if not(a->'targetIds' ? (p_event->>'id')) then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
  return orulo_audit.control_paged(p_action,p_run,p_sequence,p_previous_hash,p_event);
 end if;
 if p_action<>'batch_finish' then return orulo_audit.control_pilot(p_action,p_run,p_sequence,p_previous_hash,p_event); end if;
 perform orulo_audit.lock_run(p_run);a:=orulo_audit.batch_auth(p_run);
 if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
 if (select count(*) from orulo_audit.entries where run_uuid=p_run and kind in ('BASELINE_V2','READBACK_V2'))<>2 then raise exception 'AUDIT_TWO_SNAPSHOTS_REQUIRED'; end if;
 comparison:=orulo_audit.compare_v2(p_run);
 if comparison->>'schemaMatch' is distinct from 'true' or comparison->>'captureStable' is distinct from 'true' then raise exception 'BATCH_SNAPSHOT_INTEGRITY_FAILED'; end if;
 with b as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and record->>4 is not null),
 d as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='READBACK_V2' and record->>4 is not null),
 x as(select coalesce(b.id,d.id) id,b.record before,d.record after from b full join d using(id)),
 checked as(select x.*,c.event->'result' result from x left join orulo_audit.entries c on c.run_uuid=p_run and c.kind='CAS_RESULT' and c.event->>'id'=x.id::text)
 select count(*) filter(where not coalesce(case when result is not null then result->>'status'='UPDATED' and result->'receipt'->>'verified'='true'
  and before->>4=result->'receipt'->>'beforeFullHash' and after->>4=result->'receipt'->>'afterFullHash' and before->>5=result->'receipt'->>'expectedBeforeContentHash' and after->>5=result->'receipt'->>'expectedAfterContentHash'
 else before->>4=after->>4 and before->>5=after->>5 end,false)),count(*) filter(where result->>'status'='UPDATED') into bad,written from checked;
 if bad<>0 then raise exception 'BATCH_UNATTRIBUTED_GLOBAL_CHANGE'; end if;
 return orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','FINISHED','eventUuid',p_event->>'eventUuid','mode','BATCH_IMAGES','batchId',a->>'batchId','masterHash',a->>'masterHash','batchManifestHash',a->>'batchManifestHash','rowsWritten',written,'comparison',comparison,'writeEnabled',false,'nextBatchAuthorized',false));
end$function$

CREATE OR REPLACE FUNCTION public.orulo_audited_cas(p_run uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare a jsonb;i orulo_audit.entries%rowtype;b orulo_audit.entries%rowtype;plan jsonb;target jsonb;expected public.properties%rowtype;j jsonb;
begin
 perform orulo_audit.require_service();perform orulo_audit.lock_run(p_run);
 if not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED' and event->>'mode'='BATCH_IMAGES') then return orulo_audit.pilot_cas_guard(p_run,p_operation); end if;
 a:=orulo_audit.batch_auth(p_run);select * into i from orulo_audit.entries where run_uuid=p_run and kind='INTENT' and operation_uuid=p_operation;
 if not found then raise exception 'AUDIT_DURABLE_INTENT_REQUIRED'; end if;
 select event into plan from orulo_audit.entries where run_uuid=p_run and sequence=(a->>'planSequence')::bigint and hash=a->>'planHash';

                                                    if a->>'batchId'='pilot-5971-images' then
                                                      if plan->>'proposalHash' is distinct from '4c6a3576d91fcca4f7c526daf7f62981df756dd9bab9bbb7f3b96a4d3c242eae'
                                                         or encode(sha256(convert_to(coalesce(plan->>'proposalText',''),'UTF8')),'hex') is distinct from plan->>'proposalHash'
                                                            or plan->'targets' is distinct from '[{"id":"55701ebd-747e-4968-92f1-647d2e6a79d9","buildingId":"5971","patches":[{"id":"251614","image_url":"https://static.orulo.com.br/images/properties/large/251614.JPG"},{"id":"251615","image_url":"https://static.orulo.com.br/images/properties/large/251615.JPG"}]}]'::jsonb
                                                              then raise exception 'PILOT5971_AUTHORIZED_PROPOSAL_INVALID'; end if;
                                                                if exists(select 1 from orulo_audit.entries where kind='CAS_RESULT' and event->>'id'='55701ebd-747e-4968-92f1-647d2e6a79d9') then raise exception 'PILOT5971_OPERATION_CONSUMED'; end if;
                                                                 end if;
                                                                  select x into target from jsonb_array_elements(plan->'targets')x where x->>'id'=i.event->>'id';
 if target is null or not(a->'targetIds' ? (i.event->>'id')) or coalesce(i.event->'expected'->'raw_data'->>'building_id',i.event->'expected'->'raw_data'->'building'->>'id') is distinct from target->>'buildingId' then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='CAS_RESULT' and event->>'id'=i.event->>'id') then raise exception 'BATCH_ROW_ALREADY_ATTEMPTED'; end if;
 select * into b from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2';
 if not found or b.created_at<clock_timestamp()-interval '5 minutes' or b.event->'snapshot'->>'membershipStable' is distinct from 'true' or (b.event->'snapshot'->>'beginSequence')::bigint <= (select sequence from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') or b.event->'snapshot'->'columns' is distinct from orulo_audit.columns_v2() then raise exception 'BATCH_FRESH_BASELINE_REQUIRED'; end if;
 select * into expected from jsonb_populate_record(null::public.properties,i.event->'expected');
 j:=to_jsonb(expected)||jsonb_build_object('created_at',expected.created_at at time zone 'UTC','updated_at',expected.updated_at at time zone 'UTC');
 if a->>'batchId'='pilot-5971-images' and plan->>'expectedFullHash' is distinct from md5(j::text) then raise exception 'PILOT5971_APPROVED_STATE_CHANGED'; end if;
 if not exists(select 1 from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and id=expected.id and record->>2=target->>'buildingId' and record->>4=md5(j::text)) then raise exception 'BATCH_EXPECTED_DIFFERS_FROM_BASELINE'; end if;
 if i.event->'desiredPlans' is distinct from orulo_audit.batch_merge(expected.raw_data,target->'patches') then raise exception 'BATCH_PATCH_DIFFERS_FROM_AUTHORIZED_PLAN'; end if;
 return orulo_audit.audited_cas_core(p_run,p_operation);
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.batch_prerequisite_result(p_batch text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
 r constant uuid := '8c3b6881-69fa-4737-a29f-6aeebe1b94b9';
 terminal_hash constant text := '4e9b652387480e73eb6c0058b8ec456bd0874ca345e4f3be1cdaf26ce40246a6';
 expected_events constant integer := 957;
 expected_rows constant integer := 26;
 expected_occurrences constant integer := 110;
 e orulo_audit.entries%rowtype; p orulo_audit.entries%rowtype;
 ok boolean; n bigint; missing_before bigint; missing_after bigint;
begin
 select * into e from orulo_audit.entries where kind='FINISHED'
 and event->>'batchId'=p_batch and event->>'masterHash'=orulo_audit.batch_catalog()->>'masterHash'
 order by created_at desc,run_uuid limit 1;
 if found then return jsonb_build_object('terminalType','FINISHED','runUuid',e.run_uuid,'sequence',e.sequence,'hash',e.hash); end if;

 if p_batch='phase2-30-a' then
  select * into e from orulo_audit.entries
   where run_uuid='28c6cb35-06da-4eb1-ab56-cf5b27dfaa5a'::uuid
   order by sequence desc limit 1;
  if not found or e.sequence<>1077 or e.kind<>'ABORTED'
     or e.event->'reconciled' is distinct from 'true'::jsonb then return null; end if;
  select count(*),bool_and(sequence=rn and previous_hash=prev
    and hash=encode(sha256(convert_to(canonical,'UTF8')),'hex')
    and canonical=jsonb_build_object('runUuid',run_uuid,'sequence',sequence,'previousHash',previous_hash,'event',event)::text
    and kind=event->>'type' and event_uuid::text=event->>'eventUuid')
  into n,ok from (select *,row_number() over(order by sequence) rn,
   coalesce(lag(hash) over(order by sequence),'') prev
   from orulo_audit.entries where run_uuid=e.run_uuid)x;
  if n<>1077 or ok is distinct from true then raise exception 'PHASE2A_CHAIN_INVALID'; end if;
  if (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and kind='WRITE_AUTHORIZED')<>1
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and kind='INTENT')<>65
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and kind='CAS_RESULT')<>65
   or (select count(distinct event->>'id') from orulo_audit.entries where run_uuid=e.run_uuid and kind='CAS_RESULT')<>65
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and event->>'stage'='BATCH_ROW_VERIFIED')<>65
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and kind='CAS_RESULT'
       and event->'result'->>'status'='UPDATED' and event->'result'->'receipt'->'verified'='true'::jsonb)<>65
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and event->>'stage'='BATCH_PLAN'
       and event->>'batchId'='phase2-30-a' and event->>'masterHash'=orulo_audit.batch_catalog()->>'masterHash'
       and event->>'batchManifestHash'=orulo_audit.batch_catalog()#>>'{batches,phase2-30-a,hash}')<>1
   or (select count(*) from orulo_audit.entries where run_uuid=e.run_uuid and event->>'stage'='BATCH_INTEGRITY'
       and event#>>'{review,counts,IN_SCOPE,contentChanges}'='65'
       and event#>>'{review,counts,OUT_OF_SCOPE,contentChanges}'='6'
       and event#>>'{review,counts,UNKNOWN,contentChanges}'='0')<>1
   then raise exception 'PHASE2A_RECONCILED_EVIDENCE_INVALID'; end if;
  return jsonb_build_object('terminalType','ABORTED','recognition','REVIEWED_CONFIRMED_WRITES_WITH_EXTERNAL_CHANGES',
    'runUuid',e.run_uuid,'sequence',e.sequence,'hash',e.hash,'batchId','phase2-30-a',
    'confirmedRows',65,'verifiedRows',65,'externalContentChanges',6);
 end if;
 if p_batch is distinct from 'phase1-20' then return null; end if;
 select * into e from orulo_audit.entries where run_uuid=r order by sequence desc limit 1;
 if not found or e.sequence<>expected_events or e.kind<>'ABORTED' or e.hash<>terminal_hash or e.event->'reconciled' is distinct from 'true'::jsonb then return null; end if;
 select count(*),bool_and(sequence=rn and previous_hash=prev
 and hash=encode(sha256(convert_to(canonical,'UTF8')),'hex')
 and canonical=jsonb_build_object('runUuid',run_uuid,'sequence',sequence,'previousHash',previous_hash,'event',event)::text
 and kind=event->>'type' and event_uuid::text=event->>'eventUuid')
 into n,ok from(select *,row_number() over(order by sequence)rn,coalesce(lag(hash) over(order by sequence),'')prev from orulo_audit.entries where run_uuid=r)x;
 if n<>expected_events or ok is distinct from true then raise exception 'BATCH_RECONCILED_CHAIN_INVALID'; end if;
 select * into p from orulo_audit.entries where run_uuid=r and event->>'stage'='BATCH_PLAN';
 if not found or p.event->>'batchId'<>'phase1-20'
 or p.event->>'masterHash' is distinct from orulo_audit.batch_catalog()->>'masterHash'
 or p.event->>'batchManifestHash' is distinct from orulo_audit.batch_catalog()->'batches'->'phase1-20'->>'hash'
 or jsonb_array_length(p.event->'targets')<>expected_rows
 or (select count(*) from orulo_audit.entries where run_uuid=r and kind='WRITE_AUTHORIZED')<>1
 or (select count(*) from orulo_audit.entries where run_uuid=r and kind='INTENT')<>expected_rows
 or (select count(*) from orulo_audit.entries where run_uuid=r and kind='CAS_RESULT')<>expected_rows
 or (select count(distinct event->>'id') from orulo_audit.entries where run_uuid=r and kind='CAS_RESULT')<>expected_rows
 or (select count(*) from orulo_audit.entries where run_uuid=r and event->>'stage'='BATCH_ROW_VERIFIED')<>expected_rows
 then raise exception 'BATCH_RECONCILED_COUNTS_INVALID'; end if;
 if exists(
 select 1 from orulo_audit.entries c
 left join orulo_audit.entries i on i.run_uuid=c.run_uuid and i.operation_uuid=c.operation_uuid and i.kind='INTENT'
 left join orulo_audit.entries v on v.run_uuid=c.run_uuid and v.operation_uuid=c.operation_uuid and v.event->>'stage'='BATCH_ROW_VERIFIED'
 left join orulo_audit.snapshot_records b on b.run_uuid=c.run_uuid and b.kind='BASELINE_V2' and b.id=(c.event->>'id')::uuid
 cross join lateral(select (i.event->'expected')||jsonb_build_object('created_at',(i.event->'expected'->>'created_at')::timestamptz at time zone 'UTC','updated_at',(i.event->'expected'->>'updated_at')::timestamptz at time zone 'UTC') before_row,
 (c.event->'result'->'row')||jsonb_build_object('created_at',(c.event->'result'->'row'->>'created_at')::timestamptz at time zone 'UTC','updated_at',(c.event->'result'->'row'->>'updated_at')::timestamptz at time zone 'UTC') after_row) j
 where c.run_uuid=r and c.kind='CAS_RESULT' and(
 i.sequence is null or v.sequence is null or b.id is null or i.sequence>=c.sequence or v.sequence<=c.sequence or i.created_xid=c.created_xid
 or c.event->'result'->>'status' is distinct from 'UPDATED'
 or c.event->'result'->'receipt'->'verified' is distinct from 'true'::jsonb
 or md5(j.before_row::text) is distinct from c.event->'result'->'receipt'->>'beforeFullHash'
 or md5(j.after_row::text) is distinct from c.event->'result'->'receipt'->>'afterFullHash'
 or md5((j.after_row-'updated_at')::text) is distinct from c.event->'result'->'receipt'->>'expectedAfterContentHash'
 or b.record->>4 is distinct from c.event->'result'->'receipt'->>'beforeFullHash'
 or v.event->>'fullHash' is distinct from c.event->'result'->'receipt'->>'afterFullHash'
 or v.event->>'contentHash' is distinct from c.event->'result'->'receipt'->>'expectedAfterContentHash'
 or (j.before_row-'raw_data'-'updated_at') is distinct from (j.after_row-'raw_data'-'updated_at')
 or ((j.before_row->'raw_data')-'building') is distinct from ((j.after_row->'raw_data')-'building')
 or ((j.before_row->'raw_data'->'building')-'floor_plans') is distinct from ((j.after_row->'raw_data'->'building')-'floor_plans')
 or i.event->'desiredPlans' is distinct from j.after_row->'raw_data'->'building'->'floor_plans'
 )) then raise exception 'BATCH_RECONCILED_RECEIPT_INVALID'; end if;
 select count(*) filter(where not orulo_audit.batch_has_image(plan)) into missing_before
 from orulo_audit.entries i cross join lateral jsonb_array_elements(i.event->'expected'->'raw_data'->'building'->'floor_plans')plan where i.run_uuid=r and i.kind='INTENT';
 select count(*),count(*) filter(where not orulo_audit.batch_has_image(plan)) into n,missing_after
 from orulo_audit.entries c cross join lateral jsonb_array_elements(c.event->'result'->'row'->'raw_data'->'building'->'floor_plans')plan where c.run_uuid=r and c.kind='CAS_RESULT';
 if missing_before<>expected_occurrences or n<>expected_occurrences or missing_after<>0 then raise exception 'BATCH_RECONCILED_IMAGES_INVALID'; end if;
 return jsonb_build_object('terminalType','ABORTED','recognition','REVIEWED_CONFIRMED_WRITES','runUuid',r,'sequence',e.sequence,'hash',e.hash,
 'batchId','phase1-20','confirmedRows',expected_rows,'verifiedRows',expected_rows,'recoveredPlanOccurrences',expected_occurrences);
end
$function$

CREATE OR REPLACE FUNCTION orulo_audit.batch_merge(raw jsonb, patches jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare x jsonb; k text; v jsonb; pattern constant text:='^https://static[.]orulo[.]com[.]br/images/properties/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+[.]([jJ][pP][eE]?[gG]|[pP][nN][gG]|[wW][eE][bB][pP])$';
begin
 if jsonb_typeof(patches) is distinct from 'array' or jsonb_array_length(patches)>1000 or jsonb_typeof(raw->'building'->'floor_plans') is distinct from 'array' then raise exception 'BATCH_PATCH_INVALID'; end if;
 if (select count(*)<>count(distinct p->>'id') from jsonb_array_elements(patches)p) then raise exception 'BATCH_DUPLICATE_PLAN_ID'; end if;
 if (select count(*)<>count(distinct p->>'id') from jsonb_array_elements(raw->'building'->'floor_plans')p) then raise exception 'BATCH_EXISTING_PLAN_IDS_INVALID'; end if;
 for x in select * from jsonb_array_elements(patches) loop
  if x->>'id' is null or x->>'image_url' is null or not(x->>'image_url'~pattern) or not exists(select 1 from jsonb_array_elements(raw->'building'->'floor_plans')p where p->>'id'=x->>'id') then raise exception 'BATCH_PATCH_PLAN_MISMATCH'; end if;
  for k,v in select * from jsonb_each(x) loop
   if k='id' then continue; end if;
   if k='images' then
    if jsonb_typeof(v) is distinct from 'array' or exists(select 1 from jsonb_array_elements(v)u where jsonb_typeof(u)<>'string' or not(u#>>'{}'~pattern)) then raise exception 'BATCH_IMAGE_URL_INVALID'; end if;
   elsif k not in ('image_url','url','2280x1800','1024x1024','520x280') or jsonb_typeof(v)<>'string' or not(v#>>'{}'~pattern) then raise exception 'BATCH_IMAGE_FIELDS_ONLY'; end if;
  end loop;
 end loop;
 return (select coalesce(jsonb_agg(case when orulo_audit.batch_has_image(p) then p else p||coalesce((select z-'id' from jsonb_array_elements(patches)z where z->>'id'=p->>'id'),'{}'::jsonb) end order by n),'[]'::jsonb) from jsonb_array_elements(raw->'building'->'floor_plans') with ordinality a(p,n));
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.cas_core(p_id uuid, p_expected jsonb, p_floor_plans jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET lock_timeout TO '5s'
AS $function$
declare
  v_row public.properties%rowtype;
  v_expected public.properties%rowtype;
  v_after public.properties%rowtype;
  v_id text;
  v_raw jsonb;
  v_before_json jsonb;
  v_after_json jsonb;
  v_image_keys constant text[] := array['image_url','images','2280x1800','1024x1024','520x280','url'];
  v_allowed constant text[] := array['5971','43126','4969','82124','49132','65646','70542','66664','52286','85474','44524','67183','20980','65572','46652','27313','70879','78437','25147','81726','51327','1707','74610','40580','63635','64647','85486','69302','4075','80450','2920','5303','4836','82828','67082','74738','71044','76145','3349','22027','3198','3272','49267','3207','86645','86646','83026','50575','79391','74267','78018','81308','81351','81348','20283','80202','27977','20632','24562','20333','71097','29350','59964','76053','66288','82011','36776','72335','31789','86526','80096','83366','51496','40196','74315','55630','20407','39280','21449','21605','84525','38041','38427','38740','86085','75973','41663','42122','42586','43537','51452','46609','21642','73923','21786','5422','41230','75971','66668','47279'];
begin
  if current_user <> 'orulo_audit_owner' then
    raise insufficient_privilege using message = 'ORULO_CAS_SERVICE_ROLE_REQUIRED';
  end if;
  if p_id is null or jsonb_typeof(p_expected) is distinct from 'object'
     or jsonb_typeof(p_floor_plans) is distinct from 'array'
     or jsonb_array_length(p_floor_plans) > 1000 then
    raise invalid_parameter_value using message = 'ORULO_CAS_INVALID_INPUT';
  end if;

  select p.* into v_row from public.properties p where p.id = p_id for update;
  if not found then return jsonb_build_object('status','NOT_FOUND','id',p_id); end if;
  v_id := coalesce(v_row.raw_data->>'building_id',v_row.raw_data->'building'->>'id');

                if v_id='5971' then
                   if p_id<>'55701ebd-747e-4968-92f1-647d2e6a79d9'::uuid
                       or p_expected->'raw_data'->>'building_id' is distinct from '5971' or p_expected->'raw_data'->'building'->>'id' is distinct from '5971'
                           or (select jsonb_agg(p->>'id' order by n) from jsonb_array_elements(p_expected->'raw_data'->'building'->'floor_plans') with ordinality a(p,n)) is distinct from '["251614","251615"]'::jsonb
                               or p_floor_plans is distinct from (select jsonb_agg(p||jsonb_build_object('image_url','https://static.orulo.com.br/images/properties/large/'||(p->>'id')||'.JPG') order by n) from jsonb_array_elements(p_expected->'raw_data'->'building'->'floor_plans') with ordinality a(p,n))
                                  then raise exception 'PILOT5971_IMAGE_URL_ONLY'; end if;
                                    end if;
                                      if v_id is null or not (v_id = any(v_allowed)) or v_row.state is distinct from 'SP'
     or v_row.source is distinct from 'novos' or v_row.active is distinct from true then
    raise insufficient_privilege using message = 'ORULO_CAS_SCOPE_DENIED';
  end if;
  if not (p_expected ?& array(select jsonb_object_keys(to_jsonb(v_row))))
     or (select count(*) from jsonb_object_keys(p_expected)) <>
        (select count(*) from jsonb_object_keys(to_jsonb(v_row))) then
    return jsonb_build_object('status','CONFLICT','id',p_id);
  end if;
  -- Cast timestamps/numerics with table types; compare the entire expected row, not just updated_at.
  select * into v_expected from jsonb_populate_record(null::public.properties,p_expected);
  if v_expected.id is distinct from p_id or jsonb_typeof(v_expected.raw_data->'building') is distinct from 'object'
     or jsonb_typeof(v_expected.raw_data->'building'->'floor_plans') is distinct from 'array' then
    return jsonb_build_object('status','CONFLICT','id',p_id);
  end if;
  -- Only image fields of existing floor plans may change. No new/reordered plans or typology edits.
  if (select coalesce(jsonb_agg(plan-v_image_keys order by n),'[]'::jsonb)
        from jsonb_array_elements(v_expected.raw_data->'building'->'floor_plans') with ordinality a(plan,n))
     is distinct from
     (select coalesce(jsonb_agg(plan-v_image_keys order by n),'[]'::jsonb)
        from jsonb_array_elements(p_floor_plans) with ordinality a(plan,n)) then
    raise invalid_parameter_value using message = 'ORULO_CAS_IMAGE_FIELDS_ONLY';
  end if;
  v_raw := jsonb_set(v_expected.raw_data,'{building,floor_plans}',p_floor_plans,false);
  if to_jsonb(v_row) is distinct from to_jsonb(v_expected) then
    -- Repeated identical operation is a no-op only if every non-authorized value still matches.
    if (to_jsonb(v_row)-'updated_at') =
       ((to_jsonb(v_expected)-'updated_at') || jsonb_build_object('raw_data',v_raw)) then
      return jsonb_build_object('status','UNCHANGED','id',p_id,'row',to_jsonb(v_row));
    end if;
    return jsonb_build_object('status','CONFLICT','id',p_id);
  end if;
  if v_row.raw_data = v_raw then
    return jsonb_build_object('status','UNCHANGED','id',p_id,'row',to_jsonb(v_row));
  end if;

  update public.properties p
     set raw_data = jsonb_set(p.raw_data,'{building,floor_plans}',p_floor_plans,false),
         updated_at = case when v_id='5971' then p.updated_at else clock_timestamp() end
   where p.id = p_id returning p.* into v_after;
  -- Roll back even trigger-induced changes outside the two permitted paths.
  if v_id='5971' and v_after.updated_at is distinct from v_row.updated_at then raise exception 'PILOT5971_NON_IMAGE_CHANGE'; end if;
  if (to_jsonb(v_after)-'updated_at'-'raw_data') is distinct from (to_jsonb(v_row)-'updated_at'-'raw_data')
     or (v_after.raw_data #- '{building,floor_plans}') is distinct from (v_row.raw_data #- '{building,floor_plans}')
     or v_after.raw_data->'building'->'floor_plans' is distinct from p_floor_plans then
    raise check_violation using message = 'ORULO_CAS_PRESERVATION_FAILED';
  end if;
  v_before_json := to_jsonb(v_row) || jsonb_build_object(
    'created_at',v_row.created_at at time zone 'UTC','updated_at',v_row.updated_at at time zone 'UTC');
  v_after_json := to_jsonb(v_after) || jsonb_build_object(
    'created_at',v_after.created_at at time zone 'UTC','updated_at',v_after.updated_at at time zone 'UTC');
  return jsonb_build_object('status','UPDATED','id',p_id,'row',to_jsonb(v_after),
    'receipt',jsonb_build_object('id',p_id,'verified',true,
      'expectedBeforeContentHash',md5((v_before_json-'updated_at')::text),
      'expectedAfterContentHash',md5((v_after_json-'updated_at')::text),
      'beforeFullHash',md5(v_before_json::text),'afterFullHash',md5(v_after_json::text),
      'allowedChangedPaths',case when v_id='5971' then jsonb_build_array('raw_data.building.floor_plans[0].image_url','raw_data.building.floor_plans[1].image_url') else jsonb_build_array('raw_data.building.floor_plans','updated_at') end));
end;
$function$

CREATE OR REPLACE FUNCTION orulo_audit.authorize_pilot(p_run uuid, p_expected_head text, p_github_run_id text, p_control_sha text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
AS $function$
                                                                       declare e orulo_audit.entries%rowtype; p public.properties%rowtype; j jsonb; proposal jsonb;
                                                                       begin
                                                                        if current_setting('role',true)='service_role' or session_user not in ('postgres','supabase_admin') then raise insufficient_privilege; end if;
                                                                         perform orulo_audit.lock_run(p_run);
                                                                          select * into e from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
                                                                           if e.event->>'batchId'='pilot-5971-images' then
                                                                             -- Serialize competing new authorizations; never consume/rewrite old receipts.
                                                                               perform pg_advisory_xact_lock(hashtextextended('orulo-pilot-5971-images',0));
                                                                                 if e.event->>'proposalHash' is distinct from '4c6a3576d91fcca4f7c526daf7f62981df756dd9bab9bbb7f3b96a4d3c242eae'
                                                                                    or encode(sha256(convert_to(coalesce(e.event->>'proposalText',''),'UTF8')),'hex') is distinct from e.event->>'proposalHash'
                                                                                      then raise exception 'PILOT5971_PROPOSAL_HASH_MISMATCH'; end if;
                                                                                        proposal:=(e.event->>'proposalText')::jsonb;
                                                                                          if proposal->>'buildingId' is distinct from '5971' or proposal->'targetIds' is distinct from '["55701ebd-747e-4968-92f1-647d2e6a79d9"]'::jsonb
                                                                                             or proposal->'planIds' is distinct from '["251614","251615"]'::jsonb
                                                                                                or e.event->'targets' is distinct from proposal->'targets'
                                                                                                  then raise exception 'PILOT5971_PROPOSAL_SCOPE_INVALID'; end if;
                                                                                                    if exists(select 1 from orulo_audit.entries where kind in ('INTENT','CAS_RESULT') and event->>'id'='55701ebd-747e-4968-92f1-647d2e6a79d9')
                                                                                                       or exists(select 1 from orulo_audit.entries a where a.kind='WRITE_AUTHORIZED' and a.event->>'batchId'='pilot-5971-images' and a.run_uuid<>p_run and not exists(select 1 from orulo_audit.entries z where z.run_uuid=a.run_uuid and z.kind in ('ABORTED','FINISHED')))
                                                                                                         then raise exception 'PILOT5971_PREVIOUS_OPERATION_REQUIRES_REVIEW'; end if;
                                                                                                           select * into p from public.properties where id='55701ebd-747e-4968-92f1-647d2e6a79d9'::uuid for update;
                                                                                                             if not found then raise exception 'PILOT5971_ROW_MISSING'; end if;
                                                                                                               j:=to_jsonb(p)||jsonb_build_object('created_at',p.created_at at time zone 'UTC','updated_at',p.updated_at at time zone 'UTC');
                                                                                                                 if e.event->>'expectedFullHash' is distinct from md5(j::text) then raise exception 'PILOT5971_APPROVED_STATE_CHANGED'; end if;
                                                                                                                  end if;
                                                                                                                   -- Existing owner/run/SHA/head/expiry/target/plan checks append the same
                                                                                                                    -- WRITE_AUTHORIZED event; no authorization is granted by installing this file.
                                                                                                                     return orulo_audit.authorize_before5971(p_run,p_expected_head,p_github_run_id,p_control_sha,p_reason);
                                                                                                                     end$function$

CREATE OR REPLACE FUNCTION orulo_audit.authorize_before5971(p_run uuid, p_expected_head text, p_github_run_id text, p_control_sha text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
AS $function$
declare e orulo_audit.entries%rowtype;r orulo_audit.runs%rowtype;c jsonb;inventory jsonb;x jsonb;expected jsonb;ids jsonb;patch_ids jsonb;prerequisite jsonb;
begin
 if current_setting('role',true)='service_role' or session_user not in ('postgres','supabase_admin') then raise insufficient_privilege; end if;
 perform orulo_audit.lock_run(p_run);select * into e from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 if e.event->>'stage' is distinct from 'BATCH_PLAN' then return orulo_audit.authorize_single_pilot(p_run,p_expected_head,p_github_run_id,p_control_sha,p_reason); end if;
 select * into r from orulo_audit.runs where run_uuid=p_run;c:=orulo_audit.batch_catalog()->'batches'->(e.event->>'batchId');
 if c is null or c->>'released' is distinct from 'true' then raise exception 'BATCH_PHASE_NOT_RELEASED'; end if;
 prerequisite:=orulo_audit.batch_prerequisite_result(c->>'prerequisite');
 if c->>'prerequisite' is not null and prerequisite is null then raise exception 'BATCH_PREVIOUS_RESULT_REQUIRED'; end if;
 if r.github_run_id is distinct from p_github_run_id or r.metadata->>'workflowSha' is distinct from p_control_sha or coalesce(p_control_sha,'')!~'^[a-f0-9]{40}$' or e.hash is distinct from p_expected_head or e.kind<>'CLIENT_READBACK' or e.created_at<clock_timestamp()-interval '10 minutes' or length(trim(p_reason))<10 or p_reason is null or exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('WRITE_AUTHORIZED','BASELINE_V2','ABORTED','FINISHED')) then raise exception 'BATCH_PLAN_OR_HEAD_INVALID'; end if;
 inventory:=orulo_audit.batch_inventory(e.event->>'batchId');
 if e.event->>'masterHash' is distinct from inventory->>'masterHash' or e.event->>'batchManifestHash' is distinct from inventory->>'batchManifestHash' or jsonb_array_length(inventory->'targets')=0 or jsonb_array_length(inventory->'targets')>500 then raise exception 'BATCH_TARGETS_INVALID'; end if;
 select jsonb_agg(z->>'id' order by z->>'id') into ids from jsonb_array_elements(inventory->'targets')z;
 if ids is distinct from e.event->'targetIds' or jsonb_array_length(e.event->'targets')<>jsonb_array_length(ids) then raise exception 'BATCH_TARGETS_CHANGED'; end if;
 if jsonb_typeof(e.event->'targets') is distinct from 'array' or (select count(*)<>count(distinct t->>'id') from jsonb_array_elements(e.event->'targets')t) then raise exception 'BATCH_DUPLICATE_TARGET'; end if;
 for x in select * from jsonb_array_elements(e.event->'targets') loop
  select v into expected from jsonb_array_elements(inventory->'targets')v where v->>'id'=x->>'id' and v->>'buildingId'=x->>'buildingId';
  select jsonb_agg(p->>'id' order by p->>'id') into patch_ids from jsonb_array_elements(x->'patches')p;
  if expected is null or patch_ids is distinct from expected->'missingPlanIds' then raise exception 'BATCH_PLAN_COVERAGE_INVALID'; end if;
  perform orulo_audit.batch_merge(raw_data,x->'patches') from public.properties where id=(x->>'id')::uuid;
 end loop;
 return orulo_audit.append(p_run,e.sequence+1,e.hash,jsonb_build_object('type','WRITE_AUTHORIZED','eventUuid',gen_random_uuid(),'mode','BATCH_IMAGES',
  'prerequisiteResult',prerequisite,'batchId',e.event->>'batchId','masterHash',inventory->>'masterHash','batchManifestHash',inventory->>'batchManifestHash','targetIds',ids,'planSequence',e.sequence,'planHash',e.hash,'controlSha',p_control_sha,'expiresAt',clock_timestamp()+interval '30 minutes','reason',p_reason));
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.admin_event(p_run uuid, p_type text, p_reason text, p_reconciled boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET synchronous_commit TO 'on'
AS $function$
declare seq bigint; previous text;
begin
 if current_setting('role',true)='service_role' or session_user not in ('postgres','supabase_admin') then raise insufficient_privilege; end if;
 if p_type not in ('WRITE_AUTHORIZED','ABORTED') or length(trim(p_reason))<10 then raise exception 'AUDIT_ADMIN_REASON_REQUIRED'; end if;
 if p_type='ABORTED' and not p_reconciled then raise exception 'AUDIT_RECONCILIATION_REQUIRED'; end if;
 perform orulo_audit.lock_run(p_run);
 select sequence+1,hash into seq,previous from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 return orulo_audit.append(p_run,seq,previous,jsonb_build_object('type',p_type,'eventUuid',gen_random_uuid(),'reason',p_reason,'reconciled',p_reconciled));
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.control_v1(p_action text, p_run uuid DEFAULT NULL::uuid, p_sequence bigint DEFAULT NULL::bigint, p_previous_hash text DEFAULT NULL::text, p_event jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare v_entry orulo_audit.entries%rowtype; result jsonb; snapshot jsonb;
begin
 perform orulo_audit.require_service();
 if p_action='health' then
  if current_setting('fsync')<>'on' or current_setting('full_page_writes')<>'on' then raise exception 'AUDIT_DURABILITY_UNVERIFIED'; end if;
  if has_table_privilege('service_role','orulo_audit.entries','INSERT,UPDATE,DELETE,TRUNCATE') or
     has_table_privilege('service_role','orulo_audit.runs','INSERT,UPDATE,DELETE,TRUNCATE') or
     has_function_privilege('service_role','public.orulo_media_cas(uuid,jsonb,jsonb)','EXECUTE') then
    raise exception 'AUDIT_PRIVILEGES_UNSAFE';
  end if;
  return jsonb_build_object('version',1,'storage','postgres','durable',true,'appendOnly',true,
   'synchronousCommit',current_setting('synchronous_commit'),'writeEnabled',false);
 end if;
 if p_action='start' then
  if not pg_try_advisory_xact_lock(hashtextextended('orulo-lote1-exclusive',0)) then raise exception 'AUDIT_CONCURRENT_RUN'; end if;
  if exists(select 1 from orulo_audit.runs r where not exists(select 1 from orulo_audit.entries e where e.run_uuid=r.run_uuid and e.kind in ('FINISHED','ABORTED'))) then raise exception 'AUDIT_ACTIVE_RUN_REQUIRES_RECONCILIATION'; end if;
  if p_run is null or p_event->>'repository' is distinct from 'mudeisp/ynteligencia' or
    p_event->>'actor' is distinct from 'mudeisp' or p_event->>'actorId' is distinct from '323805541' or
    p_event->>'triggeringActor' is distinct from 'mudeisp' or p_event->>'eventName' is distinct from 'workflow_dispatch' or
    p_event->>'ref' is distinct from 'refs/heads/main' or p_event->>'attempt' is distinct from '1' or
    p_event->>'approvedSha' is distinct from '2fa6ec8b093346e1a2319e4c6833cdfb0c52825e' or
    p_event->>'manifestHash' is distinct from '1c8b002b5a3b4b6caf614e3b4e6d84383b8e306ae2773f3d7de48cc7daaa6d03' or
    coalesce(p_event->>'workflowSha','') !~ '^[0-9a-f]{40}$' then
    raise exception 'AUDIT_MANUAL_OWNER_SCOPE_REQUIRED';
  end if;
  insert into orulo_audit.runs(run_uuid,github_run_id,metadata) values(p_run,p_event->>'githubRunId',p_event);
  return orulo_audit.append(p_run,1,'',p_event||jsonb_build_object('type','START'));
 end if;
 if p_action in ('read','recover') then
  if p_action='read' then
   select * into v_entry from orulo_audit.entries where run_uuid=p_run and sequence=p_sequence;
   if not found then raise exception 'AUDIT_ENTRY_NOT_FOUND'; end if;
   return jsonb_build_object('runUuid',p_run,'sequence',v_entry.sequence,'hash',v_entry.hash,'canonical',v_entry.canonical,'event',v_entry.event);
  end if;
  return jsonb_build_object('intent',(select event from orulo_audit.entries where run_uuid=p_run and kind='INTENT' and operation_uuid=(p_event->>'operationId')::uuid),
   'result',(select event from orulo_audit.entries where run_uuid=p_run and kind='CAS_RESULT' and operation_uuid=(p_event->>'operationId')::uuid));
 end if;
 perform orulo_audit.lock_run(p_run);
 if p_action='append' then
  if p_event->>'type' not in ('READ_ONLY_PREFLIGHT','CLIENT_READBACK','CLIENT_STOP','INTENT') then raise exception 'AUDIT_RESERVED_EVENT_TYPE'; end if;
  if p_event->>'type'='INTENT' then
   if not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') then raise exception 'AUDIT_OPERATIONAL_WRITE_BLOCKED'; end if;
   if not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2') or
      (p_event->>'operationId') is null or orulo_audit.scope_ok(p_event->'expected') is distinct from true or
      p_event->>'id' is distinct from p_event->'expected'->>'id' then raise exception 'AUDIT_INTENT_SCOPE_INVALID'; end if;
   if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(
    select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
  end if;
  return orulo_audit.append(p_run,p_sequence,p_previous_hash,p_event);
 end if;
 if p_action='snapshot' then
  if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(
   select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
  if p_event->>'kind' not in ('BASELINE_V2','READBACK_V2') then raise exception 'AUDIT_SNAPSHOT_KIND_INVALID'; end if;
  if p_event->>'kind'='READBACK_V2' and not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2') then raise exception 'AUDIT_BASELINE_REQUIRED'; end if;
  snapshot:=orulo_audit.snapshot_rows();
  return orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type',p_event->>'kind','eventUuid',p_event->>'eventUuid','snapshot',snapshot));
 end if;
 if p_action='finish' then
  if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') then raise exception 'AUDIT_PREFLIGHT_FINISH_ONLY'; end if;
  if (select count(*) from orulo_audit.entries where run_uuid=p_run and kind in ('BASELINE_V2','READBACK_V2'))<>2 then raise exception 'AUDIT_TWO_SNAPSHOTS_REQUIRED'; end if;
  result:=orulo_audit.compare_v2(p_run);
  return orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','FINISHED','eventUuid',p_event->>'eventUuid','comparison',result,'writeEnabled',false))
   ||jsonb_build_object('comparison',result,'writeEnabled',false);
 end if;
 raise exception 'AUDIT_ACTION_DENIED';
end$function$

CREATE OR REPLACE FUNCTION orulo_audit.audited_cas_core(p_run uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET synchronous_commit TO 'on'
 SET lock_timeout TO '5s'
AS $function$
declare intent orulo_audit.entries%rowtype; result jsonb; receipt jsonb; seq bigint; previous text;
begin
 perform orulo_audit.require_service();perform orulo_audit.lock_run(p_run);
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('FINISHED','ABORTED')) then raise exception 'AUDIT_RUN_CLOSED'; end if;
 if not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') then raise exception 'AUDIT_OPERATIONAL_WRITE_BLOCKED'; end if;
 select * into intent from orulo_audit.entries where run_uuid=p_run and operation_uuid=p_operation and kind='INTENT';
 if not found then raise exception 'AUDIT_DURABLE_INTENT_REQUIRED'; end if;
 if intent.created_xid=pg_current_xact_id() then raise exception 'AUDIT_INTENT_MUST_BE_PREVIOUSLY_COMMITTED'; end if;
 if exists(select 1 from orulo_audit.entries where operation_uuid=p_operation and kind='CAS_RESULT') then raise exception 'AUDIT_DUPLICATE_OPERATION_USE_RECOVERY'; end if;
 select sequence+1,hash into seq,previous from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 if seq<>intent.sequence+1 then raise exception 'AUDIT_INTENT_NOT_CURRENT'; end if;
 result:=orulo_audit.cas_core((intent.event->>'id')::uuid,intent.event->'expected',intent.event->'desiredPlans');
 receipt:=orulo_audit.append(p_run,seq,previous,jsonb_build_object('type','CAS_RESULT','eventUuid',gen_random_uuid(),'operationId',p_operation,'id',intent.event->>'id','result',result));
 return result||jsonb_build_object('auditReceipt',receipt);
end$function$
